:root {
  --brand: #1d4ed8;
  --brand-dark: #1e3a8a;
  --radius: 8px;
  --space: 1rem;
}

h1 {
  color: var(--brand-dark);
}

a {
  color: var(--brand);
}

.card {
  border: 1px solid var(--brand);
  border-radius: var(--radius);
  padding: var(--space);
}

button {
  background: var(--brand);
  color: white;
  border: none;
  border-radius: var(--radius);
  padding: calc(var(--space) / 2) var(--space);
}

:root {
  --brand: #1d4ed8;
}

a,
button {
  color: var(--brand);
}

button {
  background: white;
  border: 2px solid var(--brand);
  padding: 0.5rem 1rem;
}

/* Inside the card every use of --brand becomes red, including the button */
.card {
  --brand: #be123c;
  border: 1px solid var(--brand);
  padding: 1rem;
}

.card {
  color: var(--card-text, #172033);        /* --card-text undefined: #172033 is used */
  gap: var(--gap, var(--space, 1rem));     /* nested fallback */
}

/* The trap: a defined but unsuitable value */
.card {
  --size: red;
  width: 300px;
  width: var(--size);   /* invalid at computed-value time: width becomes auto, not 300px */
}

:root {
  --space: 0.5rem;
  --hue: 220;
}

h1 {
  color: hsl(var(--hue) 80% 40%);
}

.card {
  background: hsl(var(--hue) 80% 96%);
  border: 1px solid hsl(var(--hue) 60% 80%);
  padding: calc(var(--space) * 3);        /* 1.5rem */
}

button {
  margin-top: calc(var(--space) * 2);     /* 1rem */
  padding: var(--space) calc(var(--space) * 2);
}

@property --angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.badge {
  background: conic-gradient(from var(--angle), #1d4ed8, #9333ea, #1d4ed8);
  transition: --angle 600ms linear;
}

.badge:hover {
  --angle: 360deg;
}
